"use client";import {FormEvent,useState} from "react";
export function InquiryForm({slug,sold}:{slug:string;sold:boolean}){const [state,setState]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setState("Sending…");const form=new FormData(e.currentTarget);const body=Object.fromEntries(form);const response=await fetch(`/api/inquiries/${slug}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const data=await response.json();setState(response.ok?data.next_step:data.detail||"Please check the form.");if(response.ok)e.currentTarget.reset()}return <form onSubmit={submit} className="formCard"><label>Request type<select name="kind" defaultValue={sold?"inquiry":"viewing"}><option value="inquiry">General inquiry</option><option value="viewing">Viewing / test drive</option><option value="offer">Make an offer</option></select></label><label>Name<input required name="name"/></label><label>Email<input required type="email" name="email"/></label><label>Phone<input required name="phone"/></label><label>Preferred time<input type="datetime-local" name="preferred_at"/></label><label>Offer amount<input type="number" min="0" name="offer_amount"/></label><label>Message<textarea name="message" rows={4}/></label><label className="consent"><input required type="checkbox" name="consent" value="true"/> I agree that the dealer may contact me.</label><button className="button">Send request</button>{state&&<p role="status">{state}</p>}</form>}
